go:github.com/riducms/ridu/field#Default.example:
package content

import (
	"github.com/riducms/ridu/field"
	"github.com/riducms/ridu/operation"
)

var Title = field.Text("title").Localized().DefaultFrom(initialTitle)

func initialTitle(
	ctx operation.DefaultContext,
) (operation.Value[string], error) {
	if ctx.Locale == "fr" {
		return operation.Present("Sans titre"), nil
	}
	// Present supplies the initial value; Empty would leave it unset.
	return operation.Present("Untitled"), nil
}

go:github.com/riducms/ridu/field#LiveVal.example:
package content

import (
	"github.com/riducms/ridu/field"
	"github.com/riducms/ridu/operation"
)

var Pricing = field.Fields{
	field.Number("price"),
	field.Number("salePrice").LiveValidate(checkSalePrice),
}

func checkSalePrice(
	ctx operation.LiveValidationContext,
	value operation.Value[float64],
) ([]operation.Issue, error) {
	salePrice, hasSalePrice := value.Get()
	price, hasPrice := ctx.Siblings.Get("price").NumberValue()
	if !hasSalePrice || !hasPrice {
		// Wait until both prices are available before comparing them.
		return nil, nil
	}
	if salePrice < price {
		return nil, nil
	}
	return []operation.Issue{{
		Code:    "sale_price",
		Message: "Sale price must be lower than the regular price.",
	}}, nil
}

